export const EVENT_TYPES={entrance:{name:'입학식',room:'gym',subject:'창체',periods:1},opening:{name:'1학기 개학식',room:'gym',subject:'창체',periods:1},reopening:{name:'2학기 개학식',room:'gym',subject:'창체',periods:1},graduation:{name:'졸업식',room:'gym',subject:'창체',periods:2},closing:{name:'학년 마무리',room:'classroom',subject:'창체',periods:1},summer:{name:'여름방학식',room:'classroom',subject:'창체',periods:1},winter:{name:'겨울방학식',room:'classroom',subject:'창체',periods:1},trip:{name:'학급 체험학습',room:'playground',subject:'창체',periods:4},swim:{name:'생존수영',room:'pool',subject:'체육',periods:5},show:{name:'11월 학예회',room:'audiovisual',subject:'창체',periods:3},market:{name:'연말 나눔장터',room:'gym',subject:'창체',periods:3},openclass:{name:'학부모 공개수업',room:'classroom',subject:null,periods:1},peer:{name:'동료장학',room:'classroom',subject:null,periods:1}};
const dateKey=d=>d.toISOString().slice(0,10);
