export function acknowledge(s){const a=ensure(s);if(a.acknowledged)return false;a.acknowledged=true;a.acceptedAt=M.stamp(s);M.addMessage(s,'all','한정우 교감','학교교육과정 확인을 받았습니다. 학교 일정·교과 편성을 바탕으로 3월 안에 학급교육과정을 세워 주세요.',{senderId:'principal',plannerScanned:true});return true;}
