export function moveEvent(s,id,day,cancel=false,reason=''){const e=s.academic?.events.find(e=>e.id===id);if(!e||e.status==='completed'||e.status==='running'||ceremonyKinds.includes(e.kind))return {error:'해당 행사는 학교의 고정 일정이거나 이미 진행했습니다.'};if(String(reason).trim().length<4)return {error:'변경 사유를 적어 주세요.'};if(!cancel&&(!Number.isInteger(day)||day<=s.day||!schoolDay(s,day)||eventsOn(s,day).length))return {error:'다른 행사와 겹치지 않는 앞으로의 등교일을 선택해 주세요.'};e.records.push({step:cancel?'취소':'일정 변경',from:e.day,to:day,reason:String(reason).slice(0,300),date:M.stamp(s)});e.status=cancel?'cancelled':'planned';if(!cancel)e.day=day;e.step=0;sync(s);return {ok:true};}
