export function hourReport(s){const a=s.academic,group=sub=>sub==='사회'||sub==='도덕'?'사회·도덕':['음악','미술'].includes(sub)?'음악·미술':s.config.grade>=5&&['과학','실과'].includes(sub)?'과학·실과':sub,band=RULE_PACK.bands.find(b=>b.grades.includes(s.config.grade)),actual={},planned={},partner={};for(const d of a.calendar.filter(d=>d.school))for(const r of daySchedule({...s,day:d.day,academic:{...a,phase:'term'}},plannedSchedule(s,d.day))){if(r.credit===false)continue;planned[group(r.subject)]=(planned[group(r.subject)]||0)+1;}for(const [sub,n] of Object.entries(a.schoolPlan.partnerTargets||{}))partner[group(sub)]=(partner[group(sub)]||0)+n;for(const r of s.lessonResults)actual[group(r.subject)]=(actual[group(r.subject)]||0)+1;return Object.entries(band.hours).map(([subject,minimum])=>({subject,minimum,planned:planned[subject]||0,partner:partner[subject]||0,actual:actual[subject]||0,short:Math.max(0,minimum-(planned[subject]||0)-(partner[subject]||0))}));}
